// Index spatial de la matiere deja imprimee - portage de
// `pipeline/step9_collision_sim.py::_PrintedGeometryIndex` (lignes 231-281).
//
// POURQUOI CE MODULE EST LE PREMIER PORTE : le profilage de `death.stl`
// (resolution 0.8) attribue a `candidates_near` 119,0 s de temps propre, plus
// 93 s de `set.add` (**1,41 milliard d'appels**) et 8,3 s de `dict.get`
// (46,7 M d'appels) qu'elle declenche - soit ~46 % du temps total du pipeline.
// Un seul portage sert QUATRE etapes : step9, step9b, step8b, step10 (+ step5).
//
// DEUX DEFAUTS DISTINCTS, mesures separement (voir plan) :
//   1. cout d'interpretation : liste de tuples materialisee par requete,
//      un `dict.get` par cellule, un `set.add` par (cellule x capsule) ;
//   2. defaut ALGORITHMIQUE : une capsule est inseree dans toutes les
//      cellules que son AABB touche, donc revisitee une fois par cellule a
//      chaque requete. C'est la limite #27/#30 de CLAUDE.md, jamais chiffree
//      jusqu'ici.
//
// Les deux modes de requete coexistent volontairement (`QueryMode`) : c'est ce
// qui permet de mesurer le gain du LANGAGE et le gain de l'ALGORITHME en deux
// chiffres separes, avec un seul build, sans reecrire le module entre les deux.
//
// DEUX SORTIES, parce que les consommateurs se repartissent en deux motifs
// (verifie en lisant les cinq sites d'appel, tous insensibles a l'ordre) :
//   - `candidates_indices` : step9 `_check_printed_part` et step8b
//     `_path_collides` bouclent sur les capsules une par une (filtre AABB puis
//     distance) - ils ont besoin des objets Python, donc des indices ;
//   - `candidates_endpoints` : step9b `_has_support_below`,
//     `_has_support_in_any_direction` et step5 `_layer_support_mask`
//     reconstruisent IMMEDIATEMENT deux tableaux (C,3) par
//     `np.array([s.start for s in candidates])`. C'est la source des 41 s de
//     `numpy.array` mesurees (817 653 requetes x ~432 candidats en mediane).
//     Leur rendre directement les tableaux supprime a la fois l'ensemble de
//     dedoublonnage, la liste d'objets et les deux compréhensions.

#pragma once

#include <cstdint>
#include <unordered_map>
#include <unordered_set>
#include <vector>

#include "apex/types.hpp"

namespace apex {

// Coordonnees entieres d'une cellule de la grille uniforme.
struct Cell {
    int64_t x = 0;
    int64_t y = 0;
    int64_t z = 0;

    bool operator==(const Cell& other) const {
        return x == other.x && y == other.y && z == other.z;
    }
};

struct CellHash {
    std::size_t operator()(const Cell& c) const noexcept {
        // hash_combine facon boost - suffisant pour des coordonnees de
        // cellules reelles (petites, denses), pas une fonction cryptographique.
        std::size_t h = static_cast<std::size_t>(c.x) * 0x9E3779B97F4A7C15ULL;
        h ^= static_cast<std::size_t>(c.y) + 0x9E3779B97F4A7C15ULL + (h << 6) + (h >> 2);
        h ^= static_cast<std::size_t>(c.z) + 0x9E3779B97F4A7C15ULL + (h << 6) + (h >> 2);
        return h;
    }
};

enum class QueryMode {
    // Transcription fidele du Python : un ensemble de hachage par requete.
    // Sert a mesurer le gain du seul changement de langage.
    Faithful = 0,
    // Dedoublonnage par estampilles : un compteur de requete et un tableau
    // `uint32_t` par capsule. O(1) sans hachage ni allocation - c'est ce qui
    // supprime les 1,41 milliard d'operations de `set.add`.
    Stamped = 1,
};

// Compteurs CUMULES sur toutes les instances de PrintedGrid du processus.
// Les compteurs par instance ne suffisent pas a la mesure : l'index est cree
// et detruit a l'interieur de `step9b.run`, donc inaccessible a l'appelant
// une fois l'etape terminee. Non proteges contre la concurrence — a revoir
// quand une etape deviendra multi-thread (aucune ne l'est aujourd'hui).
struct GlobalStats {
    std::uint64_t visits = 0;
    std::uint64_t uniques = 0;
    std::uint64_t queries = 0;
    std::uint64_t appends = 0;
};

GlobalStats& global_stats();
void reset_global_stats();

class PrintedGrid {
public:
    PrintedGrid(double cell_size, double radius, QueryMode mode);

    // Insere une capsule d'indice implicite `size()`, en calculant son AABB
    // exactement comme `_segment_aabb`.
    void append(const Vec3& start, const Vec3& end);

    // Indices des capsules dont l'AABB touche une cellule touchee par `box`.
    // Sur-ensemble exact des vrais candidats, comme la version Python : le
    // filtrage fin reste a la charge de l'appelant.
    void candidates(const AABB& box, std::vector<int32_t>& out) const;

    const Vec3& start_of(int32_t index) const { return starts_[static_cast<std::size_t>(index)]; }
    const Vec3& end_of(int32_t index) const { return ends_[static_cast<std::size_t>(index)]; }

    std::int64_t size() const { return count_; }
    double radius() const { return radius_; }
    QueryMode mode() const { return mode_; }
    void set_mode(QueryMode mode) { mode_ = mode; }

    // Nombre total de VISITES (cellule x capsule) et de candidats UNIQUES
    // rendus depuis la construction. Leur rapport est le facteur de
    // duplication de la grille - la mesure qui dit si le defaut restant est le
    // langage ou l'algorithme. Instrumentation explicite, jamais un silence
    // sur ce que fait le mecanisme.
    std::uint64_t visit_count() const { return visits_; }
    std::uint64_t unique_count() const { return uniques_; }
    std::uint64_t query_count() const { return queries_; }
    void reset_stats() const { visits_ = 0; uniques_ = 0; queries_ = 0; }

private:
    void cell_range(const AABB& box, Cell& lo, Cell& hi) const;

    double cell_size_;
    double radius_;
    QueryMode mode_;
    std::int64_t count_ = 0;
    std::vector<Vec3> starts_;
    std::vector<Vec3> ends_;
    std::unordered_map<Cell, std::vector<int32_t>, CellHash> grid_;

    // Etat du mode Stamped et compteurs. `mutable` car `candidates()` est
    // logiquement const (elle n'altere pas l'index) mais doit incrementer
    // l'estampille et les compteurs.
    mutable std::vector<std::uint32_t> stamp_;
    mutable std::uint32_t current_stamp_ = 0;
    mutable std::uint64_t visits_ = 0;
    mutable std::uint64_t uniques_ = 0;
    mutable std::uint64_t queries_ = 0;
};

}  // namespace apex

===== cpp/include/apex/support.hpp =====
// Test de support d'un point contre des capsules - portage de
// `core/geometry_utils.py::point_has_support_along_direction`.
//
// POURQUOI CE MODULE EST LE TROISIEME PORTE : apres les pas 1 (index spatial)
// et 2 (cinematique inverse), le re-profilage de death.stl @ 0.8 la place en
// tete des postes PORTABLES avec 11,97 s de temps propre pour 273 146 appels,
// plus ~10 s de dispatch numpy qu'elle declenche (`cross`,
// `normalize_axis_tuple`, `moveaxis`) - soit ~22 s des 98,2 s profilees. Le
// seul poste plus gros est TetGen lui-meme (16,6 s), qui est deja natif et
// incompressible.
//
// LE VRAI LEVIER EST L'ARRET ANTICIPE, PAS LE LANGAGE. La fonction ne rend
// qu'un BOOLEEN ("existe-t-il un appui ?") et execute pourtant ~15 operations
// numpy sur les ~690 candidats a chaque appel, sans jamais court-circuiter.
// Mesure a l'appui : la grille rend 690,6 candidats uniques par requete en
// moyenne, et ce nombre ne depend PAS de la structure spatiale (un BVH
// parfait rendrait les memes). C'est donc ici, et non dans l'index, que se
// trouve le plancher identifie au pas 1.
//
// EQUIVALENCE : meme construction de base orthonormee que
// `_perpendicular_basis` (reference fixe [1,0,0], repli [0,1,0] au-dela de
// 0.9), meme projection scalaire clampee, memes comparaisons. L'arret
// anticipe ne change pas le resultat : `np.any(...)` est vrai des qu'un
// candidat satisfait les trois conditions, donc s'arreter au premier rend
// exactement la meme reponse.

#pragma once

#include <cstdint>

#include "apex/types.hpp"

namespace apex {

// `position` a-t-il un appui parmi les segments `starts[i]`-`ends[i]` le long
// de `direction_up` ? Un candidat supporte le point si son point le plus
// proche est STRICTEMENT en dessous (`delta_up > 1e-9`), a moins de
// `vertical_height` en dessous, et a moins de `horizontal_radius`
// transversalement.
bool point_has_support_along_direction(const Vec3& position, const Vec3& direction_up,
                                       const double* starts, const double* ends,
                                       std::int64_t candidate_count, double horizontal_radius,
                                       double vertical_height);

// Variante multi-directions : les MEMES candidats sont testes pour chaque
// direction, avec court-circuit des la premiere qui donne un appui.
// Transcription de `step9b._has_support_in_any_direction` et de la boucle de
// `step5._layer_support_mask`, qui font exactement cela cote Python - mais en
// repayant tout le cout vectoriel a chaque direction.
bool point_has_support_in_any_direction(const Vec3& position, const double* directions,
                                        std::int64_t direction_count, const double* starts,
                                        const double* ends, std::int64_t candidate_count,
                                        double horizontal_radius, double vertical_height);

}  // namespace apex

===== cpp/include/apex/tet_topology.hpp =====
// Tables topologiques d'un maillage tetraedrique - portage de
// `step4_field_solver._tet_face_table` et `step1_ingest._build_tet_adjacency`.
//
// POURQUOI CE MODULE EST LE QUATRIEME PORTE : apres les pas 1-3, le
// re-profilage de death.stl @ 0.8 (66,5 s profilees) designe ces deux
// fonctions comme la plus grosse grappe portable restante, TetGen mis a part
// (15,7 s, deja natif et incompressible) :
//   - `_tet_face_table`      : 1,79 s + 1,78 s de generateur sur 12,5 M
//                              appels, plus une part des 2,37 s de `sorted`
//                              et des 1,43 s de `setdefault` -> ~6-7 s ;
//   - `_build_tet_adjacency` : 2,91 s + 1,35 s de `set.add` -> ~4,3 s.
// Les deux construisent la meme chose - une table de sous-simplexes avec un
// dictionnaire a cles tuple - d'ou un seul module pour les deux.
//
// CONTRAT D'EQUIVALENCE : l'ordre des faces frontiere suit l'ordre
// d'INSERTION (premiere occurrence en balayant les tetraedres dans l'ordre,
// puis les 4 faces locales dans l'ordre (0,1,2), (0,1,3), (0,2,3), (1,2,3)),
// et non l'ordre trie des cles. C'est l'ordre d'iteration du dict Python, dont
// depend l'ordre des lignes de `boundary_face_nodes` - donc celui de la
// requete kdtree en aval dans `_map_boundary_faces_to_surface`. Un ordre
// different produirait des tableaux permutes et des comparaisons faussees.
//
// Pour les ARETES (adjacence noeud-noeud) l'ordre est en revanche sans
// importance : `scipy.sparse.csr_matrix` trie ses indices a la construction,
// donc la matrice finale est identique quel que soit l'ordre fourni. Verifie,
// pas suppose.

#pragma once

#include <cstdint>
#include <vector>

namespace apex {

struct TetFaceTopology {
    // Faces n'appartenant qu'a UN seul tetraedre, dans l'ordre d'insertion.
    std::vector<int32_t> boundary_face_nodes;  // K*3, triplets tries
    std::vector<int32_t> boundary_face_tets;   // K
    // Paires de tetraedres partageant une face interne.
    std::vector<int32_t> adjacency_pairs;      // M*2
};

// `tetrahedra` : N*4 indices de noeuds, ligne-majeur.
TetFaceTopology compute_tet_face_topology(const int64_t* tetrahedra, int64_t tet_count);

// Aretes uniques (a < b) du maillage, 6 par tetraedre avant dedoublonnage.
// Rend un tableau plat M*2.
std::vector<int32_t> compute_unique_edges(const int64_t* tetrahedra, int64_t tet_count);

}  // namespace apex

