1	// Bindings pybind11 - ECHAFAUDAGE DE MIGRATION, pas un livrable.
2	//
3	// La cible est un moteur 100 % C++ ; ces bindings existent pour que les 305
4	// tests pytest servent d'ORACLE D'EQUIVALENCE pendant tout le portage (le
5	// Python et le C++ coexistent dans le meme processus, donc un test peut
6	// appeler les deux et les comparer). Ils seront retires a la bascule finale.
7	
8	#include <pybind11/pybind11.h>
9	#include <pybind11/numpy.h>
10	#include <pybind11/stl.h>
11	
12	#include <stdexcept>
13	#include <vector>
14	
15	#include "apex/kinematics.hpp"
16	#include "apex/printed_index.hpp"
17	#include "apex/support.hpp"
18	#include "apex/tet_topology.hpp"
19	#include "apex/types.hpp"
20	
21	namespace py = pybind11;
22	
23	namespace {
24	
25	using DoubleArray = py::array_t<double, py::array::c_style | py::array::forcecast>;
26	
27	// Lit un point (3,) depuis un tableau numpy quelconque (converti si besoin).
28	apex::Vec3 read_vec3(const DoubleArray& array, const char* name) {
29	    if (array.size() != 3) {
30	        throw std::invalid_argument(std::string(name) + " doit contenir exactement 3 valeurs");
31	    }
32	    const double* data = array.data();
33	    return apex::Vec3{data[0], data[1], data[2]};
34	}
35	
36	// Enveloppe Python de PrintedGrid : elle ajoute la conversion numpy et les
37	// deux formes de sortie attendues par les cinq sites d'appel.
38	class PyPrintedGrid {
39	public:
40	    PyPrintedGrid(double cell_size, double radius, int mode)
41	        : grid_(cell_size, radius,
42	                mode == 1 ? apex::QueryMode::Stamped : apex::QueryMode::Faithful) {}
43	
44	    void append(const DoubleArray& start, const DoubleArray& end) {
45	        grid_.append(read_vec3(start, "start"), read_vec3(end, "end"));
46	    }
47	
48	    // Insertion en LOT. Le chemin historique appelait `append` une fois par
49	    // capsule depuis Python - 744 324 franchissements de frontiere sur
50	    // death.stl, plus un `_segment_aabb` numpy par capsule : ~4 s mesurees
51	    // (1,79 + 1,19 + 1,01) pour une operation triviale. La granularite de
52	    // l'appel coutait plus cher que le calcul lui-meme.
53	    void append_batch(const DoubleArray& starts, const DoubleArray& ends) {
54	        if (starts.ndim() != 2 || starts.shape(1) != 3) {
55	            throw std::invalid_argument("starts doit etre de forme (N,3)");
56	        }
57	        if (ends.shape(0) != starts.shape(0) || ends.ndim() != 2 || ends.shape(1) != 3) {
58	            throw std::invalid_argument("ends doit avoir la meme forme que starts");
59	        }
60	        const auto count = static_cast<std::int64_t>(starts.shape(0));
61	        const double* s = starts.data();
62	        const double* e = ends.data();
63	
64	        py::gil_scoped_release release;
65	        for (std::int64_t i = 0; i < count; ++i) {
66	            grid_.append(apex::Vec3{s[3 * i], s[3 * i + 1], s[3 * i + 2]},
67	                         apex::Vec3{e[3 * i], e[3 * i + 1], e[3 * i + 2]});
68	        }
69	    }
70	
71	    // Motif A : step9 `_check_printed_part`, step8b `_path_collides`. Ils
72	    // bouclent capsule par capsule cote Python et ont besoin des objets, donc
73	    // des indices dans leur propre liste `_segments`.
74	    py::array_t<std::int32_t> candidates_indices(const DoubleArray& lo,
75	                                                 const DoubleArray& hi) {
76	        query(lo, hi);
77	        py::array_t<std::int32_t> out(static_cast<py::ssize_t>(buffer_.size()));
78	        if (!buffer_.empty()) {
79	            std::copy(buffer_.begin(), buffer_.end(), out.mutable_data());
80	        }
81	        return out;
82	    }
83	
84	    // Motif B : step9b `_has_support_below` / `_has_support_in_any_direction`
85	    // et step5 `_layer_support_mask`. Ils construisaient deux tableaux (C,3)
86	    // par comprehension sur les objets candidats - 41 s de `numpy.array`
87	    // mesurees. On les leur rend directement.
88	    py::tuple candidates_endpoints(const DoubleArray& lo, const DoubleArray& hi) {
89	        query(lo, hi);
90	        const auto count = static_cast<py::ssize_t>(buffer_.size());
91	
92	        py::array_t<double> starts({count, static_cast<py::ssize_t>(3)});
93	        py::array_t<double> ends({count, static_cast<py::ssize_t>(3)});
94	        double* s = starts.mutable_data();
95	        double* e = ends.mutable_data();
96	
97	        for (py::ssize_t i = 0; i < count; ++i) {
98	            const apex::Vec3& a = grid_.start_of(buffer_[static_cast<std::size_t>(i)]);
99	            const apex::Vec3& b = grid_.end_of(buffer_[static_cast<std::size_t>(i)]);
100	            s[3 * i + 0] = a.x;
101	            s[3 * i + 1] = a.y;
102	            s[3 * i + 2] = a.z;
103	            e[3 * i + 0] = b.x;
104	            e[3 * i + 1] = b.y;
105	            e[3 * i + 2] = b.z;
106	        }
107	        return py::make_tuple(std::move(starts), std::move(ends));
108	    }
109	
110	    // FUSION requete spatiale + test de support. C'est le point d'entree qui
111	    // rapporte : il ne materialise JAMAIS les ~690 candidats cote Python.
112	    // L'ancien chemin allouait deux tableaux (C,3) par appel (3,95 s mesurees
113	    // rien que dans `candidates_endpoints`), puis Python executait ~15
114	    // operations numpy dessus pour ne rendre qu'un booleen (11,97 s + ~10 s de
115	    // dispatch numpy). Ici, les extremites sont lues directement dans la
116	    // grille et la boucle s'arrete au premier appui trouve.
117	    bool has_support(const DoubleArray& lo, const DoubleArray& hi, const DoubleArray& position,
118	                     const DoubleArray& directions, double horizontal_radius,
119	                     double vertical_height) {
120	        query(lo, hi);
121	        if (buffer_.empty()) {
122	            return false;
123	        }
124	        if (directions.ndim() != 2 || directions.shape(1) != 3) {
125	            throw std::invalid_argument("directions doit etre de forme (D,3)");
126	        }
127	
128	        // Extremites des candidats, compactees une fois par requete dans un
129	        // tampon reutilise (pas d'allocation par appel).
130	        starts_buffer_.resize(buffer_.size() * 3);
131	        ends_buffer_.resize(buffer_.size() * 3);
132	        for (std::size_t i = 0; i < buffer_.size(); ++i) {
133	            const apex::Vec3& a = grid_.start_of(buffer_[i]);
134	            const apex::Vec3& b = grid_.end_of(buffer_[i]);
135	            starts_buffer_[3 * i + 0] = a.x;
136	            starts_buffer_[3 * i + 1] = a.y;
137	            starts_buffer_[3 * i + 2] = a.z;
138	            ends_buffer_[3 * i + 0] = b.x;
139	            ends_buffer_[3 * i + 1] = b.y;
140	            ends_buffer_[3 * i + 2] = b.z;
141	        }
142	
143	        const apex::Vec3 point = read_vec3(position, "position");
144	        const auto direction_count = static_cast<std::int64_t>(directions.shape(0));
145	        const auto candidate_count = static_cast<std::int64_t>(buffer_.size());
146	        const double* directions_data = directions.data();
147	
148	        py::gil_scoped_release release;
149	        return apex::point_has_support_in_any_direction(
150	            point, directions_data, direction_count, starts_buffer_.data(), ends_buffer_.data(),
151	            candidate_count, horizontal_radius, vertical_height);
152	    }
153	
154	    std::int64_t size() const { return grid_.size(); }
155	    void set_mode(int mode) {
156	        grid_.set_mode(mode == 1 ? apex::QueryMode::Stamped : apex::QueryMode::Faithful);
157	    }
158	    int mode() const { return grid_.mode() == apex::QueryMode::Stamped ? 1 : 0; }
159	
160	    py::dict stats() const {
161	        py::dict d;
162	        d["visits"] = grid_.visit_count();
163	        d["uniques"] = grid_.unique_count();
164	        d["queries"] = grid_.query_count();
165	        const auto uniques = grid_.unique_count();
166	        d["duplication_factor"] =
167	            uniques == 0 ? 0.0
168	                         : static_cast<double>(grid_.visit_count()) / static_cast<double>(uniques);
169	        return d;
170	    }
171	    void reset_stats() const { grid_.reset_stats(); }
172	
173	private:
174	    void query(const DoubleArray& lo, const DoubleArray& hi) {
175	        apex::AABB box;
176	        box.lo = read_vec3(lo, "min_corner");
177	        box.hi = read_vec3(hi, "max_corner");
178	        grid_.candidates(box, buffer_);
179	    }
180	
181	    apex::PrintedGrid grid_;
182	    std::vector<std::int32_t> buffer_;
183	    // Tampons reutilises entre requetes - une allocation par appel serait le
184	    // cout meme que ce chemin existe pour supprimer.
185	    std::vector<double> starts_buffer_;
186	    std::vector<double> ends_buffer_;
187	};
