191	PYBIND11_MODULE(apex_core, m) {
192	    m.doc() = "Noyau C++ du moteur Apex Slicer (portage en cours)";
193	    m.attr("__version__") = "0.1.0";
194	
195	    m.def("selftest_roundtrip",
196	          [](const DoubleArray& a) {
197	              // Verification minimale du pas 0 : la chaine numpy -> C++ ->
198	              // numpy rend exactement le tableau d'entree.
199	              py::array_t<double> out(a.size());
200	              std::copy(a.data(), a.data() + a.size(), out.mutable_data());
201	              return out;
202	          },
203	          "Aller-retour numpy trivial, pour valider la chaine de build.");
204	
205	    m.def(
206	        "resolve_axis_angles_batch",
207	        [](const DoubleArray& desired_directions, const DoubleArray& positions,
208	           const py::list& axes_spec, const DoubleArray& reference_direction,
209	           const py::object& platform_origin, double singularity_radius_epsilon,
210	           const py::object& initial_previous_angles) {
211	            if (desired_directions.ndim() != 2 || desired_directions.shape(1) != 3) {
212	                throw std::invalid_argument("desired_directions doit etre de forme (N,3)");
213	            }
214	            if (positions.ndim() != 2 || positions.shape(1) != 3) {
215	                throw std::invalid_argument("positions doit etre de forme (N,3)");
216	            }
217	            if (positions.shape(0) != desired_directions.shape(0)) {
218	                throw std::invalid_argument("positions et desired_directions de tailles differentes");
219	            }
220	
221	            std::vector<apex::AxisSpec> axes;
222	            axes.reserve(axes_spec.size());
223	            for (const auto& item : axes_spec) {
224	                const auto tuple = item.cast<py::tuple>();
225	                const auto axis = tuple[0].cast<DoubleArray>();
226	                axes.push_back(apex::AxisSpec{read_vec3(axis, "axis"), tuple[1].cast<double>(),
227	                                              tuple[2].cast<double>()});
228	            }
229	
230	            apex::Vec3 origin_value{};
231	            const apex::Vec3* origin_ptr = nullptr;
232	            if (!platform_origin.is_none()) {
233	                origin_value = read_vec3(platform_origin.cast<DoubleArray>(), "platform_origin");
234	                origin_ptr = &origin_value;
235	            }
236	
