        axis = 1;
    }
    if (max_v[2] - min_v[2] > span) {
        axis = 2;
    }

    const std::int64_t mid = lo + (hi - lo) / 2;
    std::nth_element(
        indices_.begin() + lo, indices_.begin() + mid, indices_.begin() + hi,
